try:
    from packagenamespaces import (
        DEFAULT_DEPTH_LIMIT,
        DepthLimitError,
        GrantStore,
        InvalidNamespaceError,
        OverlapError,
        UnknownGrantError,
        grants_overlap,
        namespace_matches,
    )
except Exception as exc:
    _IMPORT_ERROR = exc
