class RepositoryIndex:
    """Model projects and grants belonging to one package repository."""

    def __init__(self, store=None, *, supports_namespaces=True,
                 grandfathered=None):
        self.store = GrantStore() if store is None else store
        self.supports_namespaces = supports_namespaces
        self.grandfathered = (GrandfatheredRegistry() if grandfathered is None
                              else grandfathered)
        self._projects = {}

    @property
    def api_version(self):
        """The JSON Simple API version supported by this repository."""
        return API_VERSION if self.supports_namespaces else LEGACY_API_VERSION

    def register_project(self, project, owner, *, grandfathered=False):
        """Register a project, optionally recording a legacy exemption."""
        project = _validated_name(project)
        _validate_owner(owner)
        if self.supports_namespaces and not grandfathered:
            authorize_upload(project, owner, self.store, self.grandfathered)
        self._projects[project] = owner
        if grandfathered:
            self.grandfathered.add(project)

    def project_owner(self, project):
        """Return a project's owner, or None if it is unknown."""
        return self._projects.get(_validated_name(project))

    def projects(self):
        """Return registered project names in sorted order."""
        return sorted(self._projects)

    def project_detail(self, project):
        """Describe a project and its current namespace ownership."""
        project = _validated_name(project)
        result = {"name": project}
        if self.supports_namespaces:
            owner = self.project_owner(project)
            matches = [{"name": grant.name, "owned": owner == grant.owner}
                       for grant in self.store.matching(project)]
            result["namespaces"] = matches or None
        return result

    def _require_support(self):
        if not self.supports_namespaces:
            raise NotSupportedError("repository does not support namespaces")

    def list_namespaces(self):
        """Return the /namespaces envelope, sorted by namespace name."""
        self._require_support()
        return {"api_version": str(API_VERSION),
                "namespaces": [{"name": name}
                               for name in self.store.namespaces()]}

    def namespace_detail(self, namespace):
        """Return /namespace/<namespace> details with direct relations."""
        self._require_support()
        grant = self.store.get(namespace)
        if grant is None:
            raise UnknownGrantError(
                f"unknown grant: {_validated_name(namespace)}"
            )
        parent = self.store.parent(grant.name)
        return {"name": grant.name, "parent": parent.name if parent else None,
                "children": [child.name
                             for child in self.store.children(grant.name)],
                "owner": grant.owner}

    def simple_html(self, project, files=()):
        """Render escaped HTML Simple API links, without namespace metadata."""
        project = _validated_name(project)
        lines = ["<!DOCTYPE html>", "<html>",
                 f"<head><title>Links for {escape(project)}</title></head>",
                 f"<body><h1>Links for {escape(project)}</h1>"]
        for file in files:
            filename = escape(file["filename"])
            url = escape(file["url"], quote=True)
            lines.append(f'<a href="{url}">{filename}</a><br>')
        lines.extend(["</body>", "</html>"])
        return "\n".join(lines) + "\n"

