"""Normalization and validation of package namespace names."""

import re

__all__ = ["normalize_name", "is_valid_namespace", "hyphen_depth"]

_SEPARATORS = re.compile(r"[-_.]+")
_VALID_NAME = re.compile(r"[A-Za-z0-9](?:[A-Za-z0-9._-]*[A-Za-z0-9])?")


def normalize_name(name):
    """Fold separator runs to hyphens and convert a string to lowercase."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    return _SEPARATORS.sub("-", name).lower()


def is_valid_namespace(name):
    """Return whether name uses ASCII package naming syntax."""
    return isinstance(name, str) and _VALID_NAME.fullmatch(name) is not None


def hyphen_depth(name):
    """Count hyphens in the normalized name."""
    return normalize_name(name).count("-")
"""Match normalized package names against namespace boundaries."""

from .normalize import normalize_name

__all__ = ["namespace_matches"]


def namespace_matches(namespace, project):
    """Match an exact namespace or a namespace followed by a hyphen."""
    namespace = normalize_name(namespace)
    project = normalize_name(project)
    return project == namespace or project.startswith(namespace + "-")
"""Upload authorization and exceptions for pre-existing projects."""

from .grants import _validated_name, _validate_owner

__all__ = [
    "CONFLICT_STATUS", "UploadConflictError", "GrandfatheredRegistry",
    "authorize_upload",
]

CONFLICT_STATUS = 409


class UploadConflictError(ValueError):
    """An upload conflicts with another owner's active namespace grant."""

    status_code = CONFLICT_STATUS

    def __init__(self, project, namespace, owner):
        self.project = _validated_name(project)
        self.namespace = _validated_name(namespace)
        self.owner = owner
        super().__init__(
            f"409 Conflict: {self.project!r} matches namespace "
            f"{self.namespace!r} owned by {owner!r}"
        )


class GrandfatheredRegistry:
    """Track exact project names exempt from namespace upload restrictions."""

    def __init__(self, projects=()):
        self._projects = set()
        for project in projects:
            self.add(project)

    def add(self, project):
        """Exempt a normalized project name."""
        self._projects.add(_validated_name(project))

    def discard(self, project):
        """Remove an exemption if present."""
        self._projects.discard(_validated_name(project))

    def covers(self, project):
        """Return whether this exact normalized project has an exemption."""
        return _validated_name(project) in self._projects

    def projects(self):
        """Return exempt project names in sorted order."""
        return sorted(self._projects)


def authorize_upload(project, owner, store, grandfathered=None):
    """Return True or raise UploadConflictError for a foreign reserved name."""
    project = _validated_name(project)
    _validate_owner(owner)
    if grandfathered is not None and grandfathered.covers(project):
        return True
    for grant in store.matching(project):
        if grant.owner != owner:
            raise UploadConflictError(project, grant.name, grant.owner)
    return True
"""Installation policies evaluated against one repository's active grants."""

from .grants import _validated_name, _validate_owner
from .matching import namespace_matches

__all__ = ["SecurityPolicy"]


class SecurityPolicy:
    """Require an allowed namespace grant and project held by one owner."""

    def __init__(self, namespaces, owner):
        _validate_owner(owner)
        if isinstance(namespaces, str):
            namespaces = [namespaces]
        self.namespaces = tuple(sorted({_validated_name(name)
                                        for name in namespaces}))
        self.owner = owner

    def allows(self, project, index):
        """Return whether index currently satisfies the policy for project."""
        project = _validated_name(project)
        if not index.supports_namespaces:
            return False
        if index.project_owner(project) != self.owner:
            return False
        for namespace in self.namespaces:
            grant = index.store.get(namespace)
            if (grant is not None and grant.owner == self.owner
                    and namespace_matches(namespace, project)):
                return True
        return False

    def evaluate(self, projects, index):
        """Return a normalized project-name to boolean decision mapping."""
        return {_validated_name(project): self.allows(project, index)
                for project in projects}
"""Command-line management of a local JSON namespace store."""

import argparse
import json
import os
from pathlib import Path
import sys
import tempfile

from .grants import _validated_name
from .metadata import RepositoryIndex
from .uploads import UploadConflictError, authorize_upload

__all__ = ["CONFLICT_EXIT", "main"]

CONFLICT_EXIT = 3
_DEFAULT_STORE = "packagenamespaces.json"


def _add_options(parser, *, defaults=False):
    default = None if defaults else argparse.SUPPRESS
    parser.add_argument("--store", metavar="FILE",
                        default=_DEFAULT_STORE if defaults else default,
                        help=f"JSON state file (default: {_DEFAULT_STORE})")
    parser.add_argument("--json", action="store_true",
                        default=False if defaults else default,
                        help="print machine-readable JSON")
    parser.add_argument("--owner", default=default,
                        help="owner for a grant, project, or upload check")
    parser.add_argument("--project", default=default,
                        help="select one project's metadata for dump")


def _parser():
    parser = argparse.ArgumentParser(
        prog="python -m packagenamespaces",
        description="Manage repository-local PEP 752 package namespaces.",
    )
    _add_options(parser, defaults=True)
    commands = parser.add_subparsers(dest="command", required=True)
    descriptions = {
        "reserve": "reserve a namespace for --owner",
        "remove": "withdraw a namespace grant",
        "register": "register a project for --owner, enforcing upload rules",
        "grandfather": "register a legacy project and exempt its uploads",
        "check-upload": "check an upload by --owner; a conflict exits 3",
        "list": "list grants in sorted order, optionally as JSON",
        "dump": "dump JSON state, or metadata for --project",
        "show": "show a grant's owner, parent, and direct children",
    }
    for name, description in descriptions.items():
        command = commands.add_parser(
            name, help=description, description=description.capitalize() + ".",
        )
        _add_options(command)
        if name in {"reserve", "remove", "show"}:
            command.add_argument("namespace", help="namespace name")
        elif name in {"register", "grandfather", "check-upload"}:
            command.add_argument("name", metavar="project",
                                 help="project name")
    return parser


def _document(index):
    return {
        "grants": {name: index.store.get(name).owner
                   for name in index.store.namespaces()},
        "projects": {name: index.project_owner(name)
                     for name in index.projects()},
